<template><view class="book-card" @click="$emit('tap', book)"><image class="cover" :src="book.cover_url" mode="aspectFill"/><view class="body"><text class="title">{{book.title}}</text><text class="meta">{{(book.authors||[]).join('、')}} · ⭐ {{book.avg_rating}}</text><view class="tags"><text v-for="t in (book.tags||[]).slice(0,3)" :key="t" class="tag">{{t}}</text></view><text v-if="book.reason" class="reason">{{book.reason}}</text></view></view></template>
<script setup>defineProps({book:{type:Object,required:true}}); defineEmits(['tap'])</script>
<style scoped>.book-card{display:flex;gap:20rpx;padding:22rpx;margin:18rpx;border-radius:28rpx;background:rgba(255,255,255,.9);box-shadow:0 20rpx 60rpx rgba(31,41,55,.1)}.cover{width:130rpx;height:190rpx;border-radius:22rpx;background:#ddd}.body{flex:1}.title{display:block;font-size:32rpx;font-weight:800;color:#111827}.meta{display:block;color:#667085;font-size:24rpx;margin:8rpx 0}.tags{display:flex;gap:8rpx;flex-wrap:wrap}.tag{font-size:20rpx;padding:6rpx 12rpx;border-radius:999rpx;background:#f2f4f7;color:#475467}.reason{display:block;margin-top:10rpx;color:#475467;font-size:24rpx;line-height:1.5}</style>
